SELECT dept_name, location, CASE WHEN budget >= 3672000 THEN 'high' WHEN budget >= 1680000 THEN 'mid' ELSE 'low' END budget_bucket, MAX(budget) max_budget, MIN(budget) min_budget, COUNT(DISTINCT budget) unique_dept_names FROM departments GROUP BY dept_name, location, CASE WHEN budget >= 3672000 THEN 'high' WHEN budget >= 1680000 THEN 'mid' ELSE 'low' END ORDER BY budget_bucket DESC, dept_name, location LIMIT 3;
